import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { Link, useNavigate } from 'react-router-dom';
import logo from '../../assets/sotacib-logo.jpg';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    const success = await login(email, password);
    if (success) navigate('/');
  };

  return (
    <div style={{ position: 'relative', minHeight: '100vh', padding: '24px' }}>
      <div style={{ position: 'absolute', top: '16px', left: '16px' }}>
        <img src={logo} alt="SOTACIB" style={{ width: '140px', height: '140px' }} />
      </div>

      <div className="auth-card max-w-md mx-auto mt-24">
        <h2 className="text-2xl font-bold text-left mb-6">Connexion</h2>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Email</label>
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />
          </div>
          <div className="form-group">
            <label>Mot de passe</label>
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required />
          </div>
          <button type="submit" className="btn btn-primary w-full">Se connecter</button>
        </form>
        <p className="text-center mt-4 text-sm">
          Pas de compte ? <Link to="/register" className="text-blue-600">Inscrivez-vous</Link>
        </p>
      </div>
    </div>
  );
};

export default Login;
